import { Scene, Rect, Arrow, Brace, Tex, Color, DOWN } from "retiam";

const scene = new Scene({ canvas });

// 1. Create annotated subject
const matrixBox = new Rect(6.0, 3.5, {
    fill: Color.fromHex("#1e293b"),
    stroke: Color.fromHex("#475569"),
    stroke_width: 0.05
});
scene.add(matrixBox);

// 2. Attach curly brace to the bottom edge
const brace = new Brace(matrixBox, {
    direction: DOWN,
    padding: 0.25,
    color: Color.fromHex("#38bdf8")
});
scene.add(brace);

// 3. Attach LaTeX label to the brace cusp
const label = new Tex("\\text{Rank}(\\mathbf{A}) = 3", {
    fontSize: 24,
    fill: Color.WHITE
});
label.nextTo(brace, DOWN, 0.2);
scene.add(label);

// 4. Connect with an annotated arrow
const arrow = new Arrow({
    points: [[-5, -3, 0], [-2, -1.8, 0]],
    tipType: "stealth",
    headLength: 0.4,
    headWidth: 0.25,
    stroke: Color.fromHex("#f59e0b"),
    stroke_width: 0.06
});
scene.add(arrow);
